import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.achievements.*;import idle.core.save.*;import java.util.*;import java.nio.file.*;
public class ProbeCheckpoint{public static void main(String[]args)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(args[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(2));System.out.printf("bangs=%d explosions=%d density=%d overflow=%d dark=%s darkSize=%s atoms=%s particles=%s gain=%s done=%d canChallenge=%s canExplode=%s\n",g.bigBangs(),g.state().explosions(),g.darkLevelOf("dark_density"),g.darkLevelOf("dark_overflow"),g.state().darkMatter(),g.state().darkMatterSize(),g.state().atoms(),g.state().particles(),g.productionPerSecond(),g.completedChallenges(),g.isChallengeUnlocked(g.challenges().get(0).id()),g.canExplode());for(DarkUpgrade up:g.darkUpgrades())if(g.canBuyDark(up.id()))System.out.printf("BUY_DARK %s cost=%s branch=%s\n",up.id(),g.darkCostOf(up.id()),up.branch());for(Challenge c:g.challenges())System.out.printf("challenge %s unlocked=%s completed=%s\n",c.id(),g.isChallengeUnlocked(c.id()),g.isChallengeCompleted(c.id()));}}
